352		default:
353			dialect = filter.DialectSQLite
354		}
355	
356		if _, err := engine.CompileToStatement(ctx, filterStr, filter.RenderOptions{Dialect: dialect}); err != nil {
357			return errors.Wrap(err, "failed to compile filter")
358		}
359		return nil
360	}
